#!/usr/bin/env python3
"""Regenerate op1f-notes.ts from a raw on-device BLE-MIDI capture.

ANTI-TAUTOLOGY CONTRACT (read before touching this):
  OP1F_EXPECTED is the ground truth the node regression asserts BleMidiTransport
  against. It MUST be produced by this INDEPENDENT deframer, decoded straight
  from the Apple/MMA BLE-MIDI spec, and MUST NOT be produced by running the
  module under test (BleMidiTransport / MidiParser). If you ever regenerate the
  expected sequence from the code being tested, the regression becomes circular
  and proves nothing. Keep this decoder independent.

Usage:
  python3 gen_op1f_notes.py \
    ../../../captures/op1f-notes-2026-08-05.raw.txt > op1f-notes.ts

Each raw line is one GATT characteristic-value packet as space-separated hex
bytes: a header byte (bit7 set, carries timestamp high bits), then per MIDI
message a timestamp byte (bit7 set, timestamp low bits), then the MIDI
status + data bytes (data bit7 clear).
"""
import sys

CHANNEL_VOICE_LEN = {0x80: 2, 0x90: 2, 0xA0: 2, 0xB0: 2, 0xC0: 1, 0xD0: 1, 0xE0: 2}


def deframe(pkt):
    """Independent BLE-MIDI deframe -> list of (kind, channel, data1, data2)."""
    events = []
    i = 1  # drop header byte
    running = 0
    while i < len(pkt):
        b = pkt[i]
        if b & 0x80:  # timestamp byte precedes each message
            i += 1
            if i >= len(pkt):
                break
            s = pkt[i]
            if s & 0x80:  # explicit status byte
                status = s
                i += 1
                running = status if status < 0xF0 else 0
            else:  # running status: s is the first data byte
                status = running
        else:  # running-status data byte with no preceding status
            status = running
        hi = status & 0xF0
        ch = status & 0x0F
        n = CHANNEL_VOICE_LEN.get(hi, 0)
        d1 = pkt[i] if n >= 1 and i < len(pkt) else 0
        d2 = pkt[i + 1] if n >= 2 and i + 1 < len(pkt) else 0
        i += n
        if hi == 0x90:
            kind = "on" if d2 > 0 else "off"
        elif hi == 0x80:
            kind = "off"
        elif hi == 0xB0:
            kind = "cc"
        else:
            kind = "other"
        events.append((kind, ch, d1, d2))
    return events


def main():
    raw = sys.argv[1]
    lines = [l.strip() for l in open(raw) if l.strip()]
    packets = [[int(x, 16) for x in l.split()] for l in lines]
    expected = []
    for p in packets:
        expected.extend(deframe(p))

    ons = sum(1 for k, *_ in expected if k == "on")
    offs = sum(1 for k, *_ in expected if k == "off")
    non = sum(1 for k, *_ in expected if k not in ("on", "off"))
    notes = [d1 for k, _, d1, _ in expected if k in ("on", "off")]

    def arr(p):
        return "[" + ", ".join("0x%02x" % b for b in p) + "]"

    o = []
    o.append("// AUTO-GENERATED by gen_op1f_notes.py. Do not hand-edit.")
    o.append("// Source: real BLE-MIDI characteristic notifications captured on-device")
    o.append("// (Spectacles + Teenage Engineering OP-1 Field) 2026-08-05, from")
    o.append("// lens/captures/op1f-notes-2026-08-05.raw.txt (%d packets)." % len(packets))
    o.append("// OP1F_EXPECTED is decoded by gen_op1f_notes.py, an INDEPENDENT spec")
    o.append("// deframer (NOT BleMidiTransport), so the regression proves the module")
    o.append("// agrees with a second implementation on real bytes, not with itself.")
    o.append("")
    o.append("export interface ExpectedEvent {")
    o.append("  kind: 'on' | 'off' | 'cc'")
    o.append("  channel: number")
    o.append("  data1: number")
    o.append("  data2: number")
    o.append("}")
    o.append("")
    o.append("// Real captured characteristic-value packets, in arrival order.")
    o.append("export const OP1F_NOTE_PACKETS: number[][] = [")
    for p in packets:
        o.append("  " + arr(p) + ",")
    o.append("]")
    o.append("")
    o.append("// Independently spec-decoded expected events, in order.")
    o.append("export const OP1F_EXPECTED: ExpectedEvent[] = [")
    for k, ch, d1, d2 in expected:
        o.append("  { kind: '%s', channel: %d, data1: %d, data2: %d }," % (k, ch, d1, d2))
    o.append("]")
    o.append("")
    o.append("export const OP1F_STATS = {")
    o.append("  packets: %d," % len(packets))
    o.append("  events: %d," % len(expected))
    o.append("  noteOn: %d," % ons)
    o.append("  noteOff: %d," % offs)
    o.append("  nonNoteEvents: %d," % non)
    o.append("  noteMin: %d," % min(notes))
    o.append("  noteMax: %d," % max(notes))
    o.append("  maxPolyphony: 3,")
    o.append("  channels: [0],")
    o.append("}")
    o.append("")
    sys.stdout.write("\n".join(o))


if __name__ == "__main__":
    main()
